import re


_PHONE_PATTERN = re.compile(r'(?<!\d)(0\d{1,2})-(\d{3,4})-(\d{4})(?!\d)')


def mask_phone(text):
    def _mask(match):
        return f"{match.group(1)}-{match.group(2)[0]}***-{match.group(3)}"

    return _PHONE_PATTERN.sub(_mask, text)

